import random

def generate_random_number():
    """Generate a random number between 1 and 100."""
    return random.randint(1, 100)

def get_user_guess():
    """Get a user guess as an integer."""
    while True:
        try:
            user_guess = int(input("Guess a number between 1 and 100: "))
            return user_guess
        except ValueError:
            print("That's not a valid number. Please try again.")

def play_game():
    """Play the game where the user guesses a random number."""
    random_number = generate_random_number()
    print(f"I've generated a random number between 1 and 100. Can you guess it?")

    while True:
        user_guess = get_user_guess()

        if user_guess < random_number:
            print("Too low! Try again.")
        elif user_guess > random_number:
            print("Too high! Try again.")
        else:
            print(f"Congratulations! You guessed the number correctly. The number was {random_number}.")
            break

if __name__ == "__main__":
    play_game()
